// Command gen-corpus embeds the canonical `schemas/**` corpus into
// internal/corpus/corpus_gen.go.
//
// Regenerate with `go generate ./...` from the `go/` module. The generated file
// is committed because Go modules are fetched from VCS: they cannot dereference
// a symlink or reach outside the module (unlike cargo), so a distributed Go
// verifier must carry the corpus in a generated source file. The
// corpus-sync test fails if this file drifts from the repo-root `schemas/`.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strconv"
)

func main() {
	root, err := repoRoot()
	if err != nil {
		fatal(err)
	}
	schemas := filepath.Join(root, "schemas")

	var paths []string
	err = filepath.WalkDir(schemas, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(schemas, p)
		if err != nil {
			return err
		}
		paths = append(paths, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		fatal(err)
	}
	sort.Strings(paths)

	var b bytes.Buffer
	b.WriteString("// SPDX-License-Identifier: Apache-2.0\n")
	b.WriteString("// SPDX-FileCopyrightText: 2026 Arman Wolkenstein-Jalili and Rigorix contributors\n")
	b.WriteString("// Code generated by scripts/gen-corpus. DO NOT EDIT.\n")
	b.WriteString("// Source of truth: the repo-root `schemas/` corpus.\n\n")
	b.WriteString("package corpus\n\n")
	b.WriteString("// files maps a path relative to `schemas/` to its exact contents.\n")
	b.WriteString("var files = map[string]string{\n")
	for _, rel := range paths {
		data, err := os.ReadFile(filepath.Join(schemas, filepath.FromSlash(rel)))
		if err != nil {
			fatal(err)
		}
		fmt.Fprintf(&b, "\t%s: %s,\n", strconv.Quote(rel), strconv.Quote(string(data)))
	}
	b.WriteString("}\n")

	out := filepath.Join(root, "go", "internal", "corpus", "corpus_gen.go")
	formatted, err := format.Source(b.Bytes())
	if err != nil {
		fatal(fmt.Errorf("format generated source: %w", err))
	}
	if err := os.WriteFile(out, formatted, 0o644); err != nil {
		fatal(err)
	}
	fmt.Printf("gen-corpus: %d files -> %s\n", len(paths), out)
}

// repoRoot walks up from the working directory to the checkout containing
// `schemas/envelope.json`.
func repoRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "schemas", "envelope.json")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("repo root (schemas/envelope.json) not found")
		}
		dir = parent
	}
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "gen-corpus:", err)
	os.Exit(1)
}
